#!/usr/bin/env node
// Generates packages/host/src/assets/icons/lucide-icons.generated.ts from the
// already-installed lucide-react package. Manual: `npm run icons:generate`. No
// build and no test may invoke it — the output is committed, and the adapter's
// shape test is what catches a bad refresh.
//
// The icon modules are imported here, at generation time only: each one reaches
// `createLucideIcon`, which imports React, and React is not the host's
// dependency. The generated file is pure data.
//
import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SRC_WEB = path.join(ROOT, "src/web");
const ICON_DIR = path.join(SRC_WEB, "node_modules/lucide-react/dist/esm/icons");
const OUT = path.join(
  SRC_WEB,
  "packages/host/src/assets/icons/lucide-icons.generated.ts",
);
const VERSION = JSON.parse(
  await readFile(
    path.join(SRC_WEB, "node_modules/lucide-react/package.json"),
    "utf8",
  ),
).version;

// The wrapper lucide's own `Icon` renders: the node data carries the children
// and the geometry, and these are the attributes every icon shares.
const OPEN =
  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">';

/** One attribute for the serialized SVG. `key` is React's and is not SVG. */
function attribute(name, value) {
  if (name === "key") return "";
  return ` ${name}="${String(value).replaceAll('"', "&quot;")}"`;
}

/** The module's own node array as markup. */
function markup(node) {
  return node
    .map(
      ([tag, attrs]) =>
        `<${tag}${Object.entries(attrs)
          .map(([name, value]) => attribute(name, value))
          .join("")}/>`,
    )
    .join("");
}

const files = (await readdir(ICON_DIR))
  .filter((name) => name.endsWith(".mjs") && !name.endsWith(".map"))
  .sort();

const icons = [];
for (const file of files) {
  const module = await import(pathToFileURL(path.join(ICON_DIR, file)).href);
  const data = module.__iconData;
  // Deprecated aliases (`activity-square` → `square-activity`) re-export the
  // canonical module and carry no data; the canonical entry is the one kept.
  if (data === undefined) continue;
  if (!Array.isArray(data.node)) {
    throw new Error(`${file} carries __iconData without a node array.`);
  }
  icons.push({
    name: typeof data.name === "string" ? data.name : file.slice(0, -4),
    svg: `${OPEN}${markup(data.node)}</svg>`,
  });
}

icons.sort((left, right) => left.name.localeCompare(right.name));

const file =
  `// Generated by scripts/generate-lucide-icons.mjs from lucide-react ${VERSION} (ISC).\n` +
  "// Do not edit; run `npm run icons:generate`.\n" +
  "export const LUCIDE_ICONS: readonly { readonly name: string; readonly svg: string }[] = [\n" +
  icons
    .map(
      (icon) =>
        `  { name: ${JSON.stringify(icon.name)}, svg: ${JSON.stringify(icon.svg)} },`,
    )
    .join("\n") +
  "\n];\n";

await mkdir(path.dirname(OUT), { recursive: true });
await writeFile(OUT, file, "utf8");
console.log(
  `Wrote ${icons.length} icons from lucide-react ${VERSION} to ${path.relative(ROOT, OUT)}.`,
);
